<?php
$page_title='Audit Log';require_once __DIR__.'/../includes/auth.php';require_admin();require_once __DIR__.'/../includes/admin-header.php';
$action=trim($_GET['action']??'');$username=trim($_GET['username']??'');$where=[];$args=[];if($action!==''){$where[]='action=?';$args[]=$action;}if($username!==''){$where[]='username LIKE ?';$args[]='%'.$username.'%';}$sql='SELECT * FROM audit_logs'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY id DESC LIMIT 500';$s=db()->prepare($sql);$s->execute($args);$logs=$s->fetchAll();$actions=db()->query('SELECT DISTINCT action FROM audit_logs ORDER BY action')->fetchAll(PDO::FETCH_COLUMN);
?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Audit Log</h1><p class="text-muted mb-0">Latest 500 security and data events</p></div></div><form class="card p-3 mb-3"><div class="row g-2"><div class="col-md-5"><input class="form-control" name="username" value="<?=e($username)?>" placeholder="Filter by username"></div><div class="col-md-5"><select class="form-select" name="action"><option value="">All actions</option><?php foreach($actions as $a):?><option <?=$a===$action?'selected':''?>><?=e($a)?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Filter</button></div></div></form><div class="card table-card"><div class="table-responsive"><table class="table table-sm align-middle mb-0"><thead><tr><th>Date</th><th>User</th><th>Action</th><th>Target</th><th>IP</th><th>Details</th></tr></thead><tbody><?php foreach($logs as $r):?><tr><td class="text-nowrap"><?=e($r['created_at'])?></td><td><?=e($r['username']?:'Guest')?></td><td><span class="badge text-bg-dark"><?=e($r['action'])?></span></td><td><?=e(($r['entity_type']?:'-').($r['entity_id']?' #'.$r['entity_id']:''))?></td><td><?=e($r['ip_address'])?></td><td><small><?=e($r['details']?:'-')?></small></td></tr><?php endforeach;?><?php if(!$logs):?><tr><td colspan="6" class="text-center py-4 text-muted">No audit events found.</td></tr><?php endif;?></tbody></table></div></div><?php require __DIR__.'/../includes/admin-footer.php';
